// --- Timeline.view.tsx ---
import { Button, EntityListModals, Icon, InfoBanner, cardActionIcon } from '@microteia/ui';
import type { RecordTabProps } from '@microteia/data';



/**
 * A tab inside a Project record, contributed by `surfaceTab({ surface: recordSurface(...) }, 'timeline')`.
 * The host renders it with `RecordTabProps`; this file only draws what the view model returns.
 *
 * The card actions are the screen's own (Form Design decides which), so "delete" here is whatever the
 * office configured for Milestones — and `EntityListModals` asks for the confirmation.
 */
export default function TimelineTab(props: RecordTabProps) {
  const vm = useTimelineViewModel(props);

  if (vm.screenMissing) {
    return <InfoBanner message={vm.t('timeline.screen-missing')} variant="warning" />;
  }

  return (
    <S.Wrapper>
      {vm.canCreate && (
        <S.Toolbar>
          <Button size="sm" onClick={vm.list.openNewRecord}>{vm.t('timeline.new')}</Button>
        </S.Toolbar>
      )}

      {vm.items.length === 0 ? (
        <S.Empty>{vm.t('timeline.empty')}</S.Empty>
      ) : (
        <S.Line>
          {vm.items.map((item) => (
            <S.Item key={item.id}>
              <S.Dot $color={item.color} />
              <S.Body $done={item.done} onClick={() => vm.list.openRecord(item.record)}>
                <S.Title $done={item.done}>{item.title}</S.Title>
                <S.When>{item.when}</S.When>
              </S.Body>
              <S.Actions>
                {vm.canUpdate && (
                  <Button
                    variant="ghost"
                    size="sm"
                    title={vm.t(item.done ? 'timeline.reopen' : 'timeline.complete')}
                    onClick={() => vm.toggleDone(item.record)}
                  >
                    <Icon name={item.done ? 'history' : 'check'} size={14} />
                  </Button>
                )}
                {item.actions.map((action) => (
                  <Button key={action.key} variant="ghost" size="sm" title={action.title} disabled={action.disabled} onClick={action.onClick}>
                    {action.active === undefined
                      ? cardActionIcon(action, 14)
                      : <S.ToggleIcon $on={action.active}>{cardActionIcon(action, 14)}</S.ToggleIcon>}
                  </Button>
                ))}
              </S.Actions>
            </S.Item>
          ))}
        </S.Line>
      )}

      <EntityListModals vm={vm.list} />
    </S.Wrapper>
  );
}

// --- Timeline.viewmodel.tsx ---
import { useCallback, useMemo } from 'react';
import { useTheme } from 'styled-components';
import { useEntityList, useUpdateRecord } from '@microteia/data';
import type { RecordTabProps } from '@microteia/data';
import { useLocaleFormat, useT } from '@microteia/i18n';
import { getConfigColor } from '@microteia/theme';

/**
 * The Milestone screen, by its UNIVERSAL id. The installed key may gain a suffix in the destination
 * office; the sourceId is the same everywhere — the same reason the tab itself is addressed by one.
 */
const MILESTONE_SOURCE_ID = 'microteia:record-tab-example:milestone';
/** The reference field that points a milestone at its project. */
const PROJECT_FIELD = 'project';
const PRIORITY_FIELD = 'priority';

const timeOf = (value: unknown): number => {
  if (!value) return 0;
  const date = value instanceof Date ? value : new Date(String(value));
  return isNaN(date.getTime()) ? 0 : date.getTime();
};

/**
 * Latest due date first. Declared OUTSIDE the component and handed to `useEntityList` as `sortRecords`,
 * so the order holds in `records` and `filteredRecords` alike — sorting by hand drifts the day someone
 * swaps the list being drawn.
 */
const byDueDateDesc = (a: { dueDate?: unknown }, b: { dueDate?: unknown }): number =>
  timeOf(b.dueDate) - timeOf(a.dueDate);

/**
 * Everything the timeline decides, so the view only draws. It receives the open record as props
 * (`RecordTabProps`) — the host hands it over, and hands it again when the record changes.
 */
export const useTimelineViewModel = ({ recordId }: RecordTabProps) => {
  const t = useT('com.microteia.record-tab-example');
  const { formatDate } = useLocaleFormat();
  const theme = useTheme();
  const updateRecord = useUpdateRecord();

  // `parent` is a LOCK, not a filter: the person cannot clear it, the card actions see
  // `surface: 'parentTab'`, and `openNewRecord()` opens the form with the project already filled in.
  const list = useEntityList(MILESTONE_SOURCE_ID, {
    parent: { fieldKey: PROJECT_FIELD, recordId },
    sortRecords: byDueDateDesc,
  });

  // The colours come from the field's own options, as the office configured them — not from here.
  const priorityOptions = useMemo(
    () => list.definition?.fields?.find((field: { key: string }) => field.key === PRIORITY_FIELD)?.options ?? [],
    [list.definition],
  );

  const items = useMemo(
    () => list.filteredRecords.map((record) => ({
      record,
      id: record.id as string,
      title: list.getCardTitle(record),
      when: record.dueDate ? formatDate(record.dueDate) : t('timeline.no-date'),
      color: getConfigColor(priorityOptions, String(record[PRIORITY_FIELD] ?? ''), theme, theme.colors.textSecondary),
      done: record.done === true,
      actions: list.getCardActions(record),
    })),
    [list, priorityOptions, formatDate, theme, t],
  );

  const toggleDone = useCallback(
    (record: { id: string; done?: boolean }) =>
      updateRecord(list.collection, record.id, { done: record.done !== true }),
    [updateRecord, list.collection],
  );

  return {
    t,
    list,
    items,
    toggleDone,
    screenMissing: !list.isLoading && !list.definition,
    canUpdate: list.canUpdate,
    canCreate: list.canCreate,
  };
};

// --- Timeline.styles.tsx ---
import { styled } from 'styled-components';

/** Every colour, size and space comes from the theme; only the dot takes the option's own colour. */
const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.md};
`;

const Toolbar = styled.div`
  display: flex;
  justify-content: flex-end;
`;

const Line = styled.ol`
  list-style: none;
  margin: 0;
  padding: 0 0 0 ${({ theme }) => theme.spacing.lg};
  border-left: 2px solid ${({ theme }) => theme.colors.border};
  display: flex;
  flex-direction: column;
  gap: ${({ theme }) => theme.spacing.md};
`;

const Item = styled.li`
  position: relative;
  display: flex;
  align-items: center;
  gap: ${({ theme }) => theme.spacing.md};
`;

const Dot = styled.span<{ $color: string }>`
  position: absolute;
  left: calc(-${({ theme }) => theme.spacing.lg} - ${({ theme }) => theme.spacing.sm} / 2 - 1px);
  width: ${({ theme }) => theme.spacing.sm};
  height: ${({ theme }) => theme.spacing.sm};
  border-radius: 50%;
  background: ${({ $color }) => $color};
`;

const Body = styled.button<{ $done: boolean }>`
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: ${({ theme }) => theme.spacing.xs};
  background: transparent;
  border: none;
  padding: 0;
  cursor: pointer;
  text-align: left;
  opacity: ${({ $done }) => ($done ? 0.6 : 1)};
`;

const Title = styled.span<{ $done: boolean }>`
  font-size: ${({ theme }) => theme.fontSizes.md};
  color: ${({ theme }) => theme.colors.text};
  text-decoration: ${({ $done }) => ($done ? 'line-through' : 'none')};
`;

const When = styled.span`
  font-size: ${({ theme }) => theme.fontSizes.sm};
  color: ${({ theme }) => theme.colors.textSecondary};
`;

const Actions = styled.div`
  display: flex;
  gap: ${({ theme }) => theme.spacing.xs};
`;

const Empty = styled.p`
  margin: 0;
  color: ${({ theme }) => theme.colors.textSecondary};
  font-size: ${({ theme }) => theme.fontSizes.sm};
`;

/**
 * An action that is a switch (it declares activeWhen) shows the record's state by colour: on in
 * success, off in danger - the same reading as the record header.
 */
const ToggleIcon = styled.span<{ $on: boolean }>`
  display: inline-flex;
  color: ${({ $on, theme }) => ($on ? theme.colors.success : theme.colors.danger)};
`;

export const S = { ToggleIcon, Wrapper, Toolbar, Line, Item, Dot, Body, Title, When, Actions, Empty };
